/* Automated test driver for Lab 12. DO NOT EDIT THIS FILE. */
public class FractionTest {

    public static void main(String[] args) {

        TestRunner.section("Construction, reduction, and sign handling");
        TestRunner.check("6/8 reduces to 3/4", "3/4", new Fraction(6, 8).toString());
        TestRunner.check("4/2 becomes the whole number 2", "2", new Fraction(4, 2).toString());
        TestRunner.check("0/5 becomes 0", "0", new Fraction(0, 5).toString());
        TestRunner.check("1/-2 moves the sign to the numerator", "-1/2", new Fraction(1, -2).toString());
        TestRunner.check("-6/-8 is positive", "3/4", new Fraction(-6, -8).toString());
        TestRunner.check("numerator of 6/8", 3, new Fraction(6, 8).getNumerator());
        TestRunner.check("denominator of 6/8", 4, new Fraction(6, 8).getDenominator());
        TestRunner.check("denominator of 0/5 is 1", 1, new Fraction(0, 5).getDenominator());

        TestRunner.section("A zero denominator is rejected");
        boolean threw = false;
        try {
            new Fraction(3, 0);
        } catch (IllegalArgumentException expected) {
            threw = true;
        }
        TestRunner.checkTrue("new Fraction(3, 0) throws IllegalArgumentException", threw);

        Fraction half = new Fraction(1, 2);
        Fraction third = new Fraction(1, 3);
        Fraction twoThirds = new Fraction(2, 3);

        TestRunner.section("Arithmetic");
        TestRunner.check("1/2 + 1/3", "5/6", half.add(third).toString());
        TestRunner.check("1/2 + 1/2 = 1", "1", half.add(half).toString());
        TestRunner.check("1/2 - 1/3", "1/6", half.subtract(third).toString());
        TestRunner.check("1/3 - 1/2 is negative", "-1/6", third.subtract(half).toString());
        TestRunner.check("1/2 * 2/3", "1/3", half.multiply(twoThirds).toString());
        TestRunner.check("1/2 / 1/3", "3/2", half.divide(third).toString());
        TestRunner.check("2/3 / 2/3 = 1", "1", twoThirds.divide(twoThirds).toString());

        TestRunner.section("Immutability");
        Fraction original = new Fraction(1, 2);
        original.add(new Fraction(1, 4));
        TestRunner.check("add() did not modify the original object", "1/2", original.toString());

        TestRunner.section("Division by zero");
        boolean threwDivide = false;
        try {
            half.divide(new Fraction(0, 7));
        } catch (IllegalArgumentException expected) {
            threwDivide = true;
        }
        TestRunner.checkTrue("dividing by 0/7 throws IllegalArgumentException", threwDivide);

        TestRunner.section("doubleValue");
        TestRunner.checkNear("1/2 as a double", 0.5, half.doubleValue(), 1e-9);
        TestRunner.checkNear("1/3 as a double", 0.3333333, third.doubleValue(), 1e-6);

        TestRunner.section("equals");
        TestRunner.checkTrue("1/2 equals 2/4 after reduction", half.equals(new Fraction(2, 4)));
        TestRunner.checkFalse("1/2 does not equal 1/3", half.equals(third));
        TestRunner.checkFalse("a Fraction does not equal null", half.equals(null));
        TestRunner.checkFalse("a Fraction does not equal a String", half.equals("1/2"));

        TestRunner.section("parse");
        TestRunner.check("parse(\"3/4\")", "3/4", Fraction.parse("3/4").toString());
        TestRunner.check("parse(\"6/8\") reduces", "3/4", Fraction.parse("6/8").toString());
        TestRunner.check("parse(\"5\") means 5/1", "5", Fraction.parse("5").toString());
        TestRunner.check("parse(\"-2/6\")", "-1/3", Fraction.parse("-2/6").toString());

        TestRunner.exitWithSummary();
    }
}
